BEGIN;
CREATE TABLE IF NOT EXISTS security_correlation_rules(id UUID PRIMARY KEY,rule_code TEXT NOT NULL,version INTEGER NOT NULL,name TEXT NOT NULL,window_seconds INTEGER NOT NULL,minimum_events INTEGER NOT NULL,minimum_entity_types INTEGER NOT NULL,severity TEXT NOT NULL,definition JSONB NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(rule_code,version));
CREATE TABLE IF NOT EXISTS security_correlation_findings(id UUID PRIMARY KEY,organization_id UUID NOT NULL,rule_code TEXT NOT NULL,rule_version INTEGER NOT NULL,severity TEXT NOT NULL,confidence NUMERIC(5,4) NOT NULL,explanation JSONB NOT NULL,event_ids UUID[] NOT NULL,entity_ids UUID[] NOT NULL,first_observed_at TIMESTAMPTZ NOT NULL,last_observed_at TIMESTAMPTZ NOT NULL,fingerprint CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,fingerprint));
CREATE INDEX IF NOT EXISTS idx_correlation_org_time ON security_correlation_findings(organization_id,last_observed_at DESC);
INSERT INTO security_correlation_rules(id,rule_code,version,name,window_seconds,minimum_events,minimum_entity_types,severity,definition) VALUES(gen_random_uuid(),'MULTI_ENTITY_ACTIVITY',1,'Multi-entity activity within event-time window',1800,2,2,'HIGH','{"strategy":"shared_entity_time_window"}') ON CONFLICT(rule_code,version) DO NOTHING;
COMMIT;
